interface IProps {
  file: string;
  width: number;
  onLoadSuccess: (pdf: any) => void;
}
export class AutoWidthPdf extends React.Component<IProps> {
  render = () => (
    <Document
      file = {this.props.file}
      onLoadSuccess = {(_: any) => this.props.onLoadSuccess(_)}
      >
      <Page
        pageNumber = {1}
        width = {this.props.width}
        />
    </Document>
  );
}
